CREATE FUNCTION public.validate_event_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k text; val jsonb; max_len integer; allowed text[]:=ARRAY['title','description','category','format','organizer','organizerDescription','date','endDate','registrationDeadline','city','campus','venue','timeZone','onlineDetails','eligibility','eligibilityDetails','skillsDetails','skills','tags','schedule','sourceName','sourceUrl','registrationUrl','isSample']; BEGIN
IF NEW.event-allowed<>'{}'::jsonb THEN RAISE EXCEPTION 'Unknown event fields'; END IF;
FOREACH k IN ARRAY ARRAY['title','description','organizer','organizerDescription','city','campus','venue','timeZone','eligibilityDetails','skillsDetails','sourceName'] LOOP
max_len:=CASE WHEN k='description' THEN 10000 WHEN k IN('title','organizer') THEN 160 WHEN k IN('city','timeZone') THEN 100 ELSE 2000 END;
IF jsonb_typeof(NEW.event->k) IS DISTINCT FROM 'string' OR length(trim(NEW.event->>k))=0 OR length(NEW.event->>k)>max_len THEN RAISE EXCEPTION 'Invalid field: %',k; END IF; END LOOP;
FOREACH k IN ARRAY ARRAY['date','endDate','registrationDeadline'] LOOP IF jsonb_typeof(NEW.event->k) IS DISTINCT FROM 'string' OR NEW.event->>k !~ '^\d{4}-\d{2}-\d{2}$' OR to_char((NEW.event->>k)::date,'YYYY-MM-DD')<>NEW.event->>k THEN RAISE EXCEPTION 'Invalid date'; END IF; END LOOP;
IF (NEW.event->>'endDate')::date<(NEW.event->>'date')::date OR (NEW.event->>'registrationDeadline')::date>(NEW.event->>'date')::date THEN RAISE EXCEPTION 'Invalid date ordering'; END IF;
FOREACH k IN ARRAY ARRAY['sourceUrl','registrationUrl'] LOOP IF jsonb_typeof(NEW.event->k) IS DISTINCT FROM 'string' OR length(NEW.event->>k)>2048 OR(coalesce(NEW.event->>k,'')<>'' AND NEW.event->>k !~ '^https?://[^[:space:]@/]+([/?#][^[:space:]]*)?$') THEN RAISE EXCEPTION 'Invalid URL'; END IF; END LOOP;
FOREACH k IN ARRAY ARRAY['eligibility','skills','tags'] LOOP IF jsonb_typeof(NEW.event->k) IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.event->k)>30 THEN RAISE EXCEPTION 'Invalid list'; END IF; FOR val IN SELECT value FROM jsonb_array_elements(NEW.event->k) LOOP IF jsonb_typeof(val)<>'string' OR length(val#>>'{}')>2000 OR length(trim(val#>>'{}'))=0 THEN RAISE EXCEPTION 'Invalid list entry'; END IF; END LOOP; END LOOP;
IF jsonb_typeof(NEW.event->'schedule') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.event->'schedule') NOT BETWEEN 1 AND 30 THEN RAISE EXCEPTION 'Invalid schedule'; END IF;
FOR val IN SELECT value FROM jsonb_array_elements(NEW.event->'schedule') LOOP IF jsonb_typeof(val->'time') IS DISTINCT FROM 'string' OR jsonb_typeof(val->'activity') IS DISTINCT FROM 'string' OR length(val->>'time') NOT BETWEEN 1 AND 100 OR length(val->>'activity') NOT BETWEEN 1 AND 2000 OR val-ARRAY['time','activity']<>'{}'::jsonb THEN RAISE EXCEPTION 'Invalid schedule entry'; END IF; END LOOP;
IF jsonb_typeof(NEW.event->'onlineDetails') IS DISTINCT FROM 'string' OR length(NEW.event->>'onlineDetails')>2000 THEN RAISE EXCEPTION 'Invalid online details'; END IF;
RETURN NEW; END; $$;
CREATE TRIGGER validate_event_payload BEFORE INSERT OR UPDATE OF event ON public.event_records FOR EACH ROW EXECUTE FUNCTION public.validate_event_record();
CREATE INDEX event_records_owner ON public.event_records(submitter_id,created_at DESC);
CREATE INDEX event_records_status ON public.event_records(status,created_at DESC);